import math

def cross_entropy_bits(p, q):
    """H(p, q) in bits. Raise ValueError if some q_i = 0 < p_i."""
    total = 0.0
    for pi, qi in zip(p, q):
        if pi == 0:
            continue
        if qi == 0:
            return math.inf
        total -= pi * math.log2(qi)
    return total
